mapper.select:
SELECT r.id, r.product_id AS productId, p.title AS productTitle, p.cover_image AS productCover, p.status AS productStatus, r.user_id AS userId, u.nickname AS reporterNickname, r.type, r.reason, r.status, r.handle_result AS handleResult, h.nickname AS handlerName, r.handle_time AS handleTime, r.create_time AS createTime FROM biz_report r LEFT JOIN biz_product p ON p.id = r.product_id LEFT JOIN sys_user u ON u.id = r.user_id LEFT JOIN sys_user h ON h.id = r.handler_id
r.deleted = 0
AND r.user_id = #{query.userId}
AND r.status = #{query.status}
AND r.type = #{query.type}
ORDER BY CASE WHEN r.status = 0 THEN 0 ELSE 1 END ASC, r.create_time DESC
